def transform(grid):
    # Color 4 the background cells enclosed by the non-background object.
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    stack = [(r, c) for r in range(h) for c in range(w)
             if (r == 0 or c == 0 or r == h-1 or c == w-1) and grid[r][c] == bg]
    seen.update(stack)
    while stack:
        r, c = stack.pop()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in seen:
                seen.add((nr,nc)); stack.append((nr,nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r,c) not in seen:
                out[r][c] = 4
    return out
